import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "सीने में दर्द? दिल अचानक तेज़ धड़कने लगे? चक्कर या सांस फूलना? ऐसे में डॉक्टर अक्सर सबसे पहले ई सी जी करवाते हैं. आज गुरुवार की हेल्थ टिप में जानिए ई सी जी टेस्ट. आखिर तक देखिए.",
 "हमारा दिल हर धड़कन के साथ एक छोटा सा बिजली का सिग्नल बनाता है. ई सी जी, यानी इलेक्ट्रोकार्डियोग्राम, इसी सिग्नल को कागज़ पर लहरों की तरह रिकॉर्ड करता है. यह दर्द रहित है. और शरीर में कोई करंट नहीं जाता, मशीन सिर्फ रिकॉर्ड करती है.",
 "डॉक्टर ई सी जी कब कहते हैं? सीने में दर्द या भारीपन. धड़कन तेज़ या अनियमित लगना. चक्कर आना या बेहोशी. सांस फूलना. और दिल के दौरे की आशंका होने पर.",
 "ई सी जी से क्या पता चलता है? दिल की धड़कन की रफ़्तार. धड़कन की लय, नियमित है या नहीं. दिल के दौरे या दिल को हुए नुकसान के संकेत. और पेसमेकर या कुछ दवाओं का दिल पर असर.",
 "भारत में लगभग हर तीन में से एक मौत, दिल और खून की नसों की बीमारियों से होती है. ऑपरेशन से पहले, पहले दिल की बीमारी रही हो, परिवार में दिल की बीमारी का मज़बूत इतिहास हो, या पेसमेकर लगा हो, तब भी डॉक्टर ई सी जी की सलाह दे सकते हैं.",
 "तैयारी बहुत आसान है. ऐसे कपड़े पहनें जो आसानी से खुल सकें. छाती पर क्रीम, तेल या पाउडर न लगाएं. टेस्ट से ठीक पहले कसरत न करें, और ठंडा पानी न पिएं. अपनी दवाओं के बारे में बताएं. टेस्ट में बस कुछ मिनट लगते हैं. लेट कर शांत और स्थिर रहें.",
 "रिपोर्ट कैसे समझें? आराम की हालत में धड़कन, आमतौर पर लगभग साठ से सौ प्रति मिनट मानी जाती है, और लय नियमित. लेकिन ई सी जी कुछ ही सेकंड की रिकॉर्डिंग है, इसलिए नॉर्मल ई सी जी हर बीमारी को खारिज नहीं करता. ज़रूरत हो तो डॉक्टर होल्टर, टी एम टी, या ईको जैसी जांच बता सकते हैं. रिपोर्ट को डॉक्टर ही आपके लक्षणों के साथ पढ़ेंगे.",
 "सीने में दर्द या दबाव, जो बांह, जबड़े, या पीठ तक जाए. साथ में पसीना, सांस फूलना, या घबराहट. ये दिल के दौरे के संकेत हो सकते हैं. महिलाओं, बुज़ुर्गों, और डायबिटीज़ वालों में कभी कभी सीने में दर्द होता ही नहीं. ऐसे में इंतज़ार न करें. तुरंत एम्बुलेंस बुलाएं, या नज़दीकी अस्पताल जाएं.",
 close_voice("क्या आपने कभी ई सी जी करवाया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/ecgr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ecg_{i}.wav"],check=True); f=f"/tmp/ecg_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ecg_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
